from pathlib import Path
import subprocess

Import("env")

project_dir = Path(env.subst("$PROJECT_DIR"))
sendspin_dir = project_dir / "sendspin-cpp"
compat_header = project_dir / "usermods" / "sendspin" / "sendspin_arduino_compat.h"
libdeps_dir = Path(env.subst("$PROJECT_LIBDEPS_DIR")) / env["PIOENV"]
websocket_revision = "b7f3de500a4fd4b58e4248093067058959833260"
websocket_checkout = libdeps_dir / ".sendspin-esp-protocols"
arduinojson_include = libdeps_dir / "ArduinoJson" / "src"
noise_include = libdeps_dir / "noise-c" / "include"

if not (sendspin_dir / "include" / "sendspin" / "client.h").is_file():
    raise RuntimeError("sendspin-cpp submodule is missing; initialize it before building")
if not (arduinojson_include / "ArduinoJson.h").is_file():
    raise RuntimeError("ArduinoJson 7.4.2 dependency was not installed")
if not (noise_include / "noise" / "protocol" / "cipherstate.h").is_file():
    raise RuntimeError("noise-c dependency was not installed")

# PlatformIO strips ESP-IDF component directories from generic library packages. Fetch the exact
# upstream revision into generated build storage and verify it before compiling the one component.
if not websocket_checkout.is_dir():
    temporary_checkout = libdeps_dir / ".sendspin-esp-protocols.tmp"
    if temporary_checkout.exists():
        raise RuntimeError(f"remove incomplete dependency checkout: {temporary_checkout}")
    temporary_checkout.mkdir(parents=True)
    subprocess.run(["git", "init", "-q", str(temporary_checkout)], check=True)
    subprocess.run([
        "git", "-C", str(temporary_checkout), "remote", "add", "origin",
        "https://github.com/espressif/esp-protocols.git",
    ], check=True)
    subprocess.run([
        "git", "-C", str(temporary_checkout), "fetch", "-q", "--depth", "1", "origin",
        websocket_revision,
    ], check=True)
    subprocess.run([
        "git", "-C", str(temporary_checkout), "checkout", "-q", "--detach", "FETCH_HEAD",
    ], check=True)
    temporary_checkout.rename(websocket_checkout)

installed_revision = subprocess.run(
    ["git", "-C", str(websocket_checkout), "rev-parse", "HEAD"],
    check=True,
    capture_output=True,
    text=True,
).stdout.strip()
if installed_revision != websocket_revision:
    raise RuntimeError(
        f"esp_websocket_client checkout is {installed_revision}, expected {websocket_revision}"
    )

websocket_dir = websocket_checkout / "components" / "esp_websocket_client"
if not (websocket_dir / "esp_websocket_client.c").is_file():
    raise RuntimeError("pinned esp_websocket_client 1.6.1 source is missing")

common_defines = [
    "SENDSPIN_ENABLE_VISUALIZER",
    ("ARDUINOJSON_ENABLE_STD_STRING", 1),
    ("ARDUINOJSON_ENABLE_STD_STREAM", 0),
    ("ARDUINOJSON_USE_LONG_LONG", 1),
    ("CONFIG_HTTPD_WS_SUPPORT", 1),
    ("CONFIG_ESP_WS_CLIENT_SEPARATE_TX_LOCK", 1),
    ("CONFIG_ESP_WS_CLIENT_TX_LOCK_TIMEOUT_MS", 2000),
]

env.AppendUnique(
    CPPPATH=[
        str(sendspin_dir / "include"),
        str(sendspin_dir / "src"),
        str(sendspin_dir / "src" / "esp"),
        str(sendspin_dir / "src" / "crypto"),
        str(arduinojson_include),
        str(noise_include),
        str(websocket_dir / "include"),
    ],
    CPPDEFINES=common_defines,
    CCFLAGS=["-include", str(compat_header)],
    CXXFLAGS=[
        "-std=gnu++20",
        "-DARDUINOJSON_ENABLE_STD_STRING=1",
        "-DARDUINOJSON_ENABLE_STD_STREAM=0",
        "-DARDUINOJSON_USE_LONG_LONG=1",
    ],
)

noise_builder_configured = False
for builder in env.GetLibBuilders():
    source_path = Path(builder.src_dir)
    if "noise-c" in (part.lower() for part in source_path.parts):
        builder.env.AppendUnique(CPPDEFINES=[
            ("NOISE_USE_CUSTOM_RAND", 1),
            ("NOISE_USE_PROTOCOL_NAME_TABLE", 1),
        ])
        noise_builder_configured = True

if not noise_builder_configured:
    raise RuntimeError("noise-c library builder was not found; cannot enable Sendspin's Noise protocol")

sendspin_sources = [
    "src/crypto/constants.cpp",
    "src/crypto/keys.cpp",
    "src/crypto/cpace.cpp",
    "src/crypto/pairing_code.cpp",
    "src/crypto/psk_wrap.cpp",
    "src/crypto/pairing_token.cpp",
    "src/noise_session.cpp",
    "src/noise_handshake.cpp",
    "src/noise_transport.cpp",
    "src/audio_stream_info.cpp",
    "src/transfer_buffer.cpp",
    "src/protocol.cpp",
    "src/time_filter.cpp",
    "src/time_burst.cpp",
    "src/connection.cpp",
    "src/connection_manager.cpp",
    "src/connection_manager_pairing.cpp",
    "src/protocol_task.cpp",
    "src/inbound_ring.cpp",
    "src/outbound_ring.cpp",
    "src/record_store.cpp",
    "src/persistence_codec.cpp",
    "src/client.cpp",
    "src/client_dispatch.cpp",
    "src/visualizer_role.cpp",
    "src/esp/server_connection.cpp",
    "src/esp/client_connection.cpp",
    "src/esp/ws_server.cpp",
    "src/esp/network_info.cpp",
    "src/esp/noise_rand.cpp",
]

sendspin_env = env.Clone()
sendspin_filter = ["-<*>"] + [f"+<{source}>" for source in sendspin_sources]
sendspin_env.BuildSources(
    str(Path(env.subst("$BUILD_DIR")) / "sendspin-cpp"),
    str(sendspin_dir),
    src_filter=sendspin_filter,
)

websocket_env = env.Clone()
websocket_env.AppendUnique(
    CPPPATH=[str(websocket_dir), str(websocket_dir / "include")],
    CPPDEFINES=[
        ("CONFIG_ESP_WS_CLIENT_SEPARATE_TX_LOCK", 1),
        ("CONFIG_ESP_WS_CLIENT_TX_LOCK_TIMEOUT_MS", 2000),
    ],
)
websocket_env.BuildSources(
    str(Path(env.subst("$BUILD_DIR")) / "esp_websocket_client"),
    str(websocket_dir),
    src_filter=["+<*.c>", "+<*.cpp>", "-<test*>", "-<examples*>", "-<managed_components*>"]
)
